  ('basmati rice', '{"long grain rice"}', 'cup', 'grocery', null, false, '{}'),
  ('plain yogurt', '{"whole milk yogurt","curd"}', 'cup', 'grocery', null, false, '{"dairy"}'),
  ('cauliflower', '{}', 'head', 'either', '{5,6,7,8,9,10}', false, '{}'),
