insert into recipes (title, cuisine_tag, body_md, time_minutes, toddler_variant_notes, source, base_servings, dietary_tags)
select v.title, v.cuisine_tag, v.body_md, v.time_minutes, v.notes, 'curated', v.base_servings, v.dietary_tags::text[]
from (values
  ('Rajma Masala', 'indian', E'Kidney beans simmered in a spiced onion-tomato gravy until thick and creamy, served over basmati.\n\n1. Saute onion in vegetable oil until deep golden, 8 minutes.\n2. Add garlic, ginger, cumin, coriander, and garam masala; cook 1 minute.\n3. Stir in crushed tomatoes and cook down 5 minutes until the oil separates.\n4. Add kidney beans and a cup of water; simmer 15 minutes, mashing some beans to thicken. Serve over basmati with cilantro.', 40, E'Pull a portion of beans and rice before the chili powder goes in; mash lightly.', 4, '{"vegan","vegetarian","dairy_free","gluten_free"}'),
  ('Chicken Tikka Masala', 'indian', E'Yogurt-marinated chicken in a creamy spiced tomato sauce, the weeknight version.\n\n1. Toss cubed chicken thighs with yogurt, garam masala, turmeric, and salt; rest 15 minutes.\n2. Sear the chicken in ghee until browned; set aside.\n3. Saute onion, garlic, and ginger, then add cumin, coriander, and crushed tomatoes; simmer 10 minutes.\n4. Stir in heavy cream, return the chicken, and simmer 5 minutes. Serve with basmati and naan.', 45, E'Set aside plain seared chicken and rice before the sauce; chop small.', 5, '{"contains_poultry","contains_dairy","gluten_free"}'),
  ('Aloo Gobi', 'indian', E'Potatoes and cauliflower roasted with turmeric and cumin until the edges catch.\n\n1. Toss cubed potato and cauliflower florets with vegetable oil, turmeric, cumin, and salt.\n2. Roast at 425F for 25 minutes, tossing once, until deeply browned at the edges.\n3. Bloom mustard seeds and ginger in a little oil, then toss with the roasted vegetables.\n4. Finish with cilantro and a squeeze of lemon; serve with basmati.', 40, E'Reserve plain roasted potato and cauliflower before the mustard seed tempering.', 4, '{"vegan","vegetarian","dairy_free","gluten_free"}'),
  ('Lamb Rogan Josh', 'indian', E'Slow-simmered lamb in a fragrant yogurt and tomato gravy warm with cardamom.\n\n1. Brown cubed lamb shoulder in ghee in batches; set aside.\n2. Saute onion until golden, then add garlic, ginger, cardamom, coriander, and garam masala.\n3. Stir in yogurt a spoonful at a time so it does not split, then add crushed tomatoes.\n4. Return the lamb with a cup of water, cover, and simmer 60 minutes until fork-tender. Serve with basmati.', 90, E'Set aside plain browned lamb pieces and rice before the spiced gravy; shred finely.', 6, '{"contains_dairy","gluten_free"}'),
  ('Chana Saag', 'indian', E'Chickpeas folded into a silky spiced spinach base, vegan and fast.\n\n1. Saute onion, garlic, and ginger in vegetable oil until soft.\n2. Add cumin, coriander, and turmeric; cook 1 minute until fragrant.\n3. Add spinach with a splash of water and cook until fully wilted, then mash or blend coarsely.\n4. Fold in chickpeas and coconut milk; simmer 10 minutes and serve over basmati.', 30, E'Reserve plain chickpeas and rice; stir in a spoon of the mild spinach base if they will take it.', 4, '{"vegan","vegetarian","dairy_free","gluten_free"}'),
  ('Butter Chicken Meatballs', 'indian', E'Chicken meatballs poached in a glossy tomato-butter sauce, faster than the classic.\n\n1. Mix ground chicken with garam masala, garlic, ginger, and salt; roll into small meatballs.\n2. Brown the meatballs in ghee; set aside.\n3. Saute onion, then add crushed tomatoes, cumin, and coriander; simmer 10 minutes.\n4. Stir in butter and heavy cream, return the meatballs, and simmer 10 minutes. Serve with basmati.', 40, E'Pull two plain browned meatballs and rice before saucing; halve them.', 5, '{"contains_poultry","contains_dairy","gluten_free"}'),
  ('Coconut Fish Curry', 'indian', E'Flaky white fish poached in a coconut curry bright with tamarind and curry leaves.\n\n1. Saute onion, garlic, and ginger in vegetable oil until soft.\n2. Add mustard seeds, turmeric, and curry powder; cook until fragrant.\n3. Pour in coconut milk and tamarind paste; simmer 5 minutes.\n4. Slide in fish fillets and poach gently 8 minutes until just opaque. Serve over basmati with cilantro.', 30, E'Flake a piece of plain poached fish and rinse it of sauce; serve with rice.', 4, '{"pescatarian","contains_fish","dairy_free","gluten_free"}'),
  ('Dal Tadka', 'indian', E'Soft red lentils finished with a sizzling cumin-garlic tempering poured over the top.\n\n1. Simmer red lentils with turmeric and salt in water until completely soft, about 20 minutes.\n2. Whisk to a loose puree, adding water as needed.\n3. In a small pan, sizzle cumin seeds, garlic, and chili in ghee until the garlic is golden.\n4. Pour the tempering over the dal, stir once, and serve with basmati.', 35, E'Ladle out plain dal and rice before the tempering goes on.', 4, '{"vegetarian","contains_dairy","gluten_free"}'),
  ('Keema Matar', 'indian', E'Spiced ground lamb with peas, a fast weeknight braise.\n\n1. Brown ground lamb in a wide pan, breaking it up; drain excess fat.\n2. Add onion, garlic, and ginger; cook until softened.\n3. Stir in cumin, coriander, garam masala, and crushed tomatoes; simmer 10 minutes.\n4. Add peas and cook 5 minutes more. Serve with basmati or naan.', 35, E'Set aside plain browned lamb and peas before the spices; mash the peas.', 5, '{"dairy_free"}'),
  ('Paneer Tikka Skewers', 'indian', E'Yogurt-marinated paneer and peppers charred under the broiler.\n\n1. Whisk yogurt with garam masala, turmeric, garlic, ginger, and salt.\n2. Toss cubed paneer, bell pepper, and red onion in the marinade; rest 20 minutes.\n3. Thread onto skewers and broil 10 minutes, turning once, until charred at the edges.\n4. Finish with lemon and cilantro; serve with basmati.', 40, E'Reserve plain paneer cubes rinsed of marinade, plus rice.', 4, '{"vegetarian","contains_dairy","gluten_free"}'),
  ('Cashew Korma with Vegetables', 'indian', E'A mild, creamy cashew-based curry loaded with cauliflower, peas, and carrot.\n\n1. Soak cashews in hot water 10 minutes, then blend smooth with a little water.\n2. Saute onion, garlic, and ginger, then add coriander, cardamom, and garam masala.\n3. Add cauliflower, carrot, and a cup of water; simmer 12 minutes until tender.\n4. Stir in the cashew cream and peas; simmer 5 minutes. Serve over basmati.', 40, E'This one is already mild — serve a small portion over rice, no changes needed.', 4, '{"vegan","vegetarian","dairy_free","gluten_free","contains_nuts"}'),
  ('Tandoori-Style Roast Chicken Thighs', 'indian', E'Yogurt-and-spice marinated thighs roasted hot until the skin blisters.\n\n1. Whisk yogurt with garam masala, turmeric, smoked paprika, garlic, ginger, lemon, and salt.\n2. Coat chicken thighs and marinate at least 20 minutes.\n3. Roast at 450F for 30 minutes until charred at the edges and cooked through.\n4. Rest 5 minutes and serve with basmati and cucumber.', 45, E'Pull a thigh before marinating if you can; otherwise wipe the marinade and shred the meat, serve with rice.', 5, '{"contains_poultry","contains_dairy","gluten_free"}'),
  ('Shakshuka', 'middle_eastern', E'Eggs poached in a smoky pepper and tomato sauce, eaten straight from the skillet with bread.\n\n1. Saute onion and bell pepper in olive oil until soft and sweet, 10 minutes.\n2. Add garlic, cumin, and smoked paprika; cook 1 minute.\n3. Pour in crushed tomatoes and simmer 10 minutes until thickened.\n4. Make wells, crack in eggs, cover, and cook 6 minutes until whites set. Finish with parsley; serve with pita.', 30, E'Scoop out a spoon of plain tomato base and a well-cooked egg before the spices build.', 4, '{"vegetarian","contains_egg","contains_gluten"}'),
  ('Chicken Shawarma Bowls', 'middle_eastern', E'Warm-spiced chicken over rice with cucumber, tomato, and a lemony tahini drizzle.\n\n1. Toss sliced chicken thighs with cumin, coriander, smoked paprika, garlic, lemon, and olive oil.\n2. Sear in a hot skillet until browned and cooked through.\n3. Whisk tahini with lemon juice, garlic, and water until pourable.\n4. Build bowls with rice, chicken, cucumber, tomato, and parsley; drizzle with tahini sauce.', 30, E'Set aside plain seared chicken and rice before the tahini; chop the chicken small.', 4, '{"contains_poultry","dairy_free","contains_sesame"}'),
  ('Mujadara', 'middle_eastern', E'Lentils and rice under a heap of deeply caramelized onions — cheap, filling, vegan.\n\n1. Cook sliced onion in olive oil over medium-low heat 20 minutes until dark and jammy; reserve half.\n2. Add rice, red lentils, cumin, and coriander to the pot with the remaining onion.\n3. Add water, bring to a boil, then cover and simmer 20 minutes until tender.\n4. Fluff, top with the reserved onions and parsley.', 45, E'Serve plain — this is already mild. A small bowl of the rice and lentils works as is.', 5, '{"vegan","vegetarian","dairy_free","gluten_free"}'),
  ('Lamb Kofta with Cucumber Yogurt', 'middle_eastern', E'Spiced lamb patties seared hard, cooled by a garlicky cucumber yogurt.\n\n1. Mix ground lamb with grated onion, garlic, cumin, coriander, dried mint, and salt.\n2. Shape into oblong patties and sear 4 minutes per side until well browned.\n3. Stir grated cucumber and garlic into yogurt with lemon and salt.\n4. Serve the kofta with pita, the cucumber yogurt, and parsley.', 30, E'Set aside a plain patty before spicing if possible; otherwise serve a small piece with plain yogurt.', 4, '{"contains_dairy","contains_gluten"}'),
  ('Falafel Bowls with Tahini', 'middle_eastern', E'Crisp baked chickpea patties over bulgur with tomato, cucumber, and tahini.\n\n1. Pulse chickpeas with onion, garlic, parsley, cumin, and coriander until coarse but holding together.\n2. Form into small patties, brush with olive oil, and bake at 425F for 25 minutes, flipping once.\n3. Cook bulgur according to package and fluff with lemon and olive oil.\n4. Build bowls with bulgur, falafel, cucumber, tomato, and a tahini drizzle.', 45, E'Reserve a plain falafel patty broken up, plus plain bulgur.', 4, '{"vegan","vegetarian","dairy_free","contains_gluten","contains_sesame"}'),
  ('Halloumi & Zaatar Traybake', 'middle_eastern', E'Chickpeas, peppers, and squeaky halloumi roasted together under a blanket of zaatar.\n\n1. Toss chickpeas, bell pepper, red onion, and cherry tomatoes with olive oil and cumin.\n2. Roast at 425F for 20 minutes.\n3. Nestle in sliced halloumi, sprinkle with zaatar, and roast 10 minutes more until the cheese browns.\n4. Finish with lemon, sumac, and parsley.', 40, E'Set aside plain roasted chickpeas and a small piece of halloumi before the zaatar.', 4, '{"vegetarian","contains_dairy","gluten_free","contains_sesame"}'),
  ('Muhammara Chicken with Couscous', 'middle_eastern', E'Seared chicken over couscous with a smoky roasted pepper and walnut sauce.\n\n1. Blend roasted bell pepper, walnuts, pomegranate molasses, cumin, and olive oil into a coarse sauce.\n2. Season and sear chicken breast until golden and cooked through; rest and slice.\n3. Steep couscous in hot broth 5 minutes, then fluff with olive oil and parsley.\n4. Plate couscous, chicken, and a generous spoon of muhammara.', 35, E'Plain sliced chicken and couscous, sauce on the side.', 4, '{"contains_poultry","dairy_free","contains_gluten","contains_nuts"}'),
  ('Stuffed Eggplant with Spiced Lentils', 'middle_eastern', E'Roasted eggplant halves filled with cumin-scented lentils and finished with pomegranate molasses.\n\n1. Halve eggplants, score, brush with olive oil, and roast cut-side down at 425F for 25 minutes.\n2. Saute onion and garlic, add cumin and coriander, then stir in cooked red lentils and crushed tomatoes.\n3. Fill the eggplant halves and return to the oven for 10 minutes.\n4. Drizzle with pomegranate molasses and scatter parsley and walnuts.', 50, E'Scoop plain roasted eggplant flesh and mash with a spoon of the lentils.', 4, '{"vegan","vegetarian","dairy_free","gluten_free","contains_nuts"}'),
  ('Tabbouleh-Stuffed Pita with Labneh', 'middle_eastern', E'Herb-heavy bulgur salad packed into warm pita with a thick smear of labneh.\n\n1. Soak bulgur in hot water 15 minutes, then drain well and cool.\n2. Toss with a very large amount of chopped parsley, tomato, cucumber, scallion, lemon, and olive oil.\n3. Warm pita and spread the inside with labneh.\n4. Stuff generously with the tabbouleh and finish with sumac.', 25, E'Serve plain warm pita with a little labneh and a few cucumber pieces on the side.', 4, '{"vegetarian","contains_dairy","contains_gluten"}'),
  ('Sumac Roast Chicken & Potatoes', 'middle_eastern', E'A one-pan roast where the potatoes cook in the chicken drippings and sumac brightens the whole thing.\n\n1. Toss quartered yukon potatoes and red onion with olive oil, cumin, and salt in a roasting pan.\n2. Rub chicken thighs with sumac, garlic, lemon, and olive oil; set them on top.\n3. Roast at 425F for 40 minutes until the skin is crisp and the potatoes are golden.\n4. Finish with more sumac, lemon, and parsley.', 55, E'Pull a piece of plain chicken and a few potatoes before the sumac finish; chop small.', 5, '{"contains_poultry","dairy_free","gluten_free"}')
) as v(title, cuisine_tag, body_md, time_minutes, notes, base_servings, dietary_tags)
where not exists (select 1 from recipes r where r.title = v.title);

