insert into recipes (title, cuisine_tag, body_md, time_minutes, toddler_variant_notes, source, base_servings, dietary_tags)
select v.title, v.cuisine_tag, v.body_md, v.time_minutes, v.notes, 'curated', v.base_servings, v.dietary_tags::text[]
from (values
  ('Greek Lemon Chicken & Orzo', 'mediterranean', E'One pan of chicken thighs over lemony orzo that soaks up all the drippings.\n\n1. Season chicken thighs with oregano, garlic, and salt; sear skin-side down until crisp.\n2. Remove chicken, then toast orzo in the same pan with garlic.\n3. Add broth and lemon juice, nestle the chicken back on top.\n4. Cover and simmer 18 minutes until the orzo is tender. Finish with feta, dill, and more lemon.', 40, E'Set aside plain orzo and shredded chicken before the feta and lemon.', 5, '{"contains_poultry","contains_dairy","contains_gluten"}'),
  ('Braised White Beans with Tomato & Feta', 'mediterranean', E'Creamy white beans stewed with tomato and oregano, baked under crumbled feta.\n\n1. Saute onion and garlic in a generous amount of olive oil until soft.\n2. Add crushed tomatoes, oregano, and a pinch of chili; simmer 10 minutes.\n3. Stir in white beans and a splash of broth; transfer to a baking dish.\n4. Crumble feta over the top and bake at 425F for 15 minutes until bubbling. Serve with bread.', 35, E'Spoon out plain beans and tomato before the feta; mash lightly.', 4, '{"vegetarian","contains_dairy","gluten_free"}'),
  ('Greek Salad Bowls with Marinated Chickpeas', 'mediterranean', E'A no-cook bowl of oregano-marinated chickpeas, cucumber, tomato, olives, and feta.\n\n1. Toss chickpeas with olive oil, red wine vinegar, oregano, and garlic; marinate 15 minutes.\n2. Chop cucumber, tomato, and red onion into large rustic pieces.\n3. Combine with olives and the marinated chickpeas.\n4. Top with feta and a heavy pour of olive oil; serve with pita.', 20, E'Plain cucumber and tomato pieces plus a few rinsed chickpeas.', 4, '{"vegetarian","contains_dairy","contains_gluten"}'),
  ('Sheet-Pan Salmon with Zucchini & Olives', 'mediterranean', E'Salmon roasted over zucchini and olives, finished with lemon and dill.\n\n1. Toss sliced zucchini and olives with olive oil, garlic, and oregano on a sheet pan.\n2. Roast at 425F for 10 minutes.\n3. Nestle salmon fillets on top, drizzle with olive oil, and roast 12 minutes more.\n4. Finish with lemon, dill, and flaky salt.', 30, E'Flake plain salmon and serve with soft roasted zucchini; skip the olives.', 4, '{"pescatarian","contains_fish","dairy_free","gluten_free"}'),
  ('Spanakopita-Style Skillet', 'mediterranean', E'All the spinach-and-feta filling of spanakopita, skipping the phyllo fuss.\n\n1. Wilt a large amount of spinach with garlic and olive oil; squeeze out the liquid and chop.\n2. Stir in feta, ricotta, dill, scallion, and beaten egg.\n3. Spread in an oiled skillet and bake at 400F for 25 minutes until set and golden.\n4. Cool 5 minutes, cut into wedges, and serve with lemon.', 40, E'A small wedge is fine as is; it is mild. Cool fully before serving.', 4, '{"vegetarian","contains_dairy","contains_egg","gluten_free"}'),
  ('Chicken Souvlaki with Tzatziki', 'mediterranean', E'Lemon-oregano chicken skewers with a cool cucumber yogurt.\n\n1. Marinate cubed chicken in lemon, olive oil, garlic, and oregano for 20 minutes.\n2. Thread onto skewers and sear or broil 12 minutes, turning, until charred and cooked.\n3. Grate cucumber, squeeze dry, and fold into greek yogurt with garlic, dill, and lemon.\n4. Serve with pita, tomato, and red onion.', 40, E'Plain chicken cubes off the skewer with a little plain yogurt.', 5, '{"contains_poultry","contains_dairy","contains_gluten"}'),
  ('Lemon Artichoke Orzo with Pine Nuts', 'mediterranean', E'Bright, briny orzo tossed with artichokes, capers, and toasted pine nuts.\n\n1. Cook orzo in salted water until al dente; reserve a little pasta water.\n2. Toast pine nuts in olive oil until golden; set aside.\n3. Saute garlic, artichoke hearts, and capers in olive oil.\n4. Toss with the orzo, lemon zest and juice, parsley, and pine nuts, loosening with pasta water.', 25, E'Reserve plain buttered orzo before the capers and lemon.', 4, '{"vegan","vegetarian","dairy_free","contains_gluten","contains_nuts"}'),
  ('Baked Cod with Tomatoes, Olives & Capers', 'mediterranean', E'Cod baked in a puttanesca-ish tomato sauce that comes together while the oven heats.\n\n1. Saute garlic in olive oil, add cherry tomatoes, and cook until they burst.\n2. Stir in olives, capers, and oregano; simmer 5 minutes.\n3. Nestle cod fillets into the sauce and spoon some over the top.\n4. Bake at 400F for 15 minutes until the fish flakes. Finish with parsley and lemon.', 30, E'Flake plain cod and rinse it of sauce; serve with a little rice or bread.', 4, '{"pescatarian","contains_fish","dairy_free","gluten_free"}'),
  ('Roasted Vegetable & Halloumi Orzo Salad', 'mediterranean', E'Warm orzo salad with charred vegetables and seared halloumi.\n\n1. Roast zucchini, bell pepper, and red onion at 425F for 25 minutes until browned.\n2. Cook orzo until al dente and toss with olive oil and lemon.\n3. Sear sliced halloumi in a dry pan until browned on both sides.\n4. Combine everything with cherry tomatoes, parsley, and a generous lemon dressing.', 40, E'Plain orzo and a small piece of halloumi; the roasted zucchini is soft enough.', 4, '{"vegetarian","contains_dairy","contains_gluten"}'),
  ('Greek Meatballs in Tomato Sauce', 'mediterranean', E'Herby beef meatballs simmered in oregano tomato sauce, served over orzo.\n\n1. Mix ground beef with grated onion, garlic, oregano, dried mint, and salt; roll into balls.\n2. Brown the meatballs in olive oil; set aside.\n3. Simmer crushed tomatoes with garlic and oregano 10 minutes.\n4. Return the meatballs and simmer 15 minutes. Serve over orzo with feta.', 45, E'Plain browned meatball halved, plus plain orzo, before the sauce.', 5, '{"contains_beef","contains_dairy","contains_gluten"}'),
  ('Pad Thai with Tofu', 'thai', E'Rice noodles tossed in a tamarind sauce with crisp tofu, egg, and peanuts.\n\n1. Soak rice noodles in hot water until pliable; drain.\n2. Whisk tamarind concentrate, fish sauce, and brown sugar into a sauce.\n3. Crisp cubed tofu in vegetable oil, push aside, scramble eggs in the pan.\n4. Add noodles and sauce, toss over high heat, then finish with scallion, peanuts, and lime.', 35, E'Plain noodles with a little oil, set aside before the sauce; skip the peanuts entirely for under-4s.', 4, '{"pescatarian","contains_egg","contains_soy","contains_nuts","contains_fish","dairy_free"}'),
  ('Thai Green Curry Chicken with Eggplant', 'thai', E'A coconut green curry with chicken, eggplant, and basil.\n\n1. Fry green curry paste in a little coconut milk until fragrant and split.\n2. Add sliced chicken and cook until nearly done.\n3. Pour in the remaining coconut milk, add eggplant and bell pepper; simmer 12 minutes.\n4. Season with fish sauce and brown sugar, finish with thai basil and lime. Serve over rice.', 35, E'Plain poached chicken and rice before the curry paste goes in.', 4, '{"contains_poultry","contains_fish","contains_shellfish","dairy_free","gluten_free"}'),
  ('Larb Tofu Lettuce Cups', 'thai', E'A vegan take on larb — crumbled tofu with lime, chili, herbs, and toasted rice.\n\n1. Crumble extra-firm tofu and fry in vegetable oil until browned and dry.\n2. Toss with lime juice, soy sauce, brown sugar, and chili.\n3. Fold in a large amount of mint, cilantro, and thinly sliced scallion.\n4. Spoon into romaine leaves and top with peanuts.', 25, E'Plain crumbled tofu with rice, no lime or chili; skip peanuts for under-4s.', 4, '{"vegan","vegetarian","dairy_free","contains_soy","contains_nuts"}'),
  ('Thai Basil Beef (Pad Krapow Neua)', 'thai', E'Fast, punchy stir-fried beef with garlic, chili, and a mountain of basil.\n\n1. Pound garlic and thai chili into a rough paste.\n2. Sear ground beef hard in a very hot pan until crisped in spots.\n3. Add the garlic-chili paste, soy sauce, fish sauce, and brown sugar; toss 1 minute.\n4. Kill the heat and fold in thai basil until just wilted. Serve over rice with a fried egg.', 20, E'Set aside plain seared beef and rice before the chili paste.', 4, '{"contains_beef","contains_fish","contains_soy","contains_gluten","dairy_free"}'),
  ('Green Papaya Salad with Shrimp', 'thai', E'Crunchy shredded green papaya in a hot-sour-sweet dressing with shrimp.\n\n1. Shred green papaya and carrot into long strands.\n2. Pound garlic and thai chili, then whisk with lime, fish sauce, and brown sugar.\n3. Poach shrimp briefly in salted water until just pink; cool.\n4. Toss everything with cherry tomatoes and peanuts just before serving.', 25, E'Plain poached shrimp chopped small and a few papaya strands with no dressing.', 4, '{"pescatarian","contains_shellfish","contains_fish","contains_nuts","dairy_free","gluten_free"}'),
  ('Massaman-Style Potato & Chickpea Curry', 'thai', E'A mild, warmly spiced coconut curry with potatoes, chickpeas, and peanuts.\n\n1. Saute onion in vegetable oil, then add curry powder, cardamom, and cinnamon.\n2. Add coconut milk, potatoes, and tamarind concentrate; simmer 20 minutes until tender.\n3. Stir in chickpeas and peanut butter until the sauce is glossy.\n4. Finish with lime and peanuts; serve over rice.', 40, E'Plain potato and chickpeas with rice; skip the peanuts for under-4s.', 4, '{"vegan","vegetarian","dairy_free","gluten_free","contains_nuts"}'),
  ('Thai Coconut Soup with Mushrooms (Tom Kha)', 'thai', E'A fragrant coconut broth sharp with lemongrass, galangal, and lime.\n\n1. Simmer coconut milk with lemongrass, galangal, and kaffir lime leaves for 10 minutes.\n2. Strain out the aromatics.\n3. Add mushrooms and simmer until tender, 5 minutes.\n4. Season with lime juice, soy sauce, and a little brown sugar; finish with cilantro and chili.', 30, E'Ladle out plain broth and soft mushrooms before the lime and chili.', 4, '{"vegan","vegetarian","dairy_free","gluten_free","contains_soy"}'),
  ('Thai Peanut Noodles with Vegetables', 'thai', E'Rice noodles in a creamy peanut sauce with crunchy raw vegetables.\n\n1. Cook rice noodles, rinse under cold water, and drain well.\n2. Whisk peanut butter, soy sauce, lime, brown sugar, garlic, and hot water into a pourable sauce.\n3. Julienne carrot, cucumber, and bell pepper.\n4. Toss noodles with sauce and vegetables; top with scallion and cilantro.', 25, E'Plain noodles with a little sesame oil; the peanut sauce is not suitable under 4.', 4, '{"vegan","vegetarian","dairy_free","contains_nuts","contains_soy","gluten_free"}')
) as v(title, cuisine_tag, body_md, time_minutes, notes, base_servings, dietary_tags)
where not exists (select 1 from recipes r where r.title = v.title);

