insert into recipes (title, cuisine_tag, body_md, time_minutes, toddler_variant_notes, source, base_servings, dietary_tags)
select v.title, v.cuisine_tag, v.body_md, v.time_minutes, v.notes, 'curated', v.base_servings, v.dietary_tags::text[]
from (values
  ('Chicken Katsu Curry', 'japanese', E'Crisp panko chicken over rice with a thick, mild Japanese curry sauce.\n\n1. Pound chicken breast thin, dredge in flour, egg, then panko; shallow-fry until deep golden.\n2. Saute onion and carrot until soft, add curry powder, and cook 1 minute.\n3. Add broth and simmer 15 minutes, then thicken with a cornstarch slurry until glossy.\n4. Slice the katsu and serve over rice with the sauce poured alongside.', 45, E'Reserve a piece of plain katsu with no sauce, cut small, plus plain rice.', 5, '{"contains_poultry","contains_gluten","contains_egg","dairy_free"}'),
  ('Miso Butter Udon with Mushrooms', 'japanese', E'Chewy udon in a savory miso butter with a pile of browned mushrooms.\n\n1. Boil udon until just tender; drain and reserve a little cooking water.\n2. Brown mushrooms hard in butter until deeply colored.\n3. Whisk miso paste with a splash of the noodle water and more butter into a loose sauce.\n4. Toss noodles and mushrooms in the sauce; finish with scallion and sesame seeds.', 25, E'Plain buttered udon set aside before the miso; snip the noodles short.', 4, '{"vegetarian","contains_dairy","contains_gluten","contains_soy","contains_sesame"}'),
  ('Salmon Teriyaki Donburi', 'japanese', E'Glazed salmon over rice with a quick homemade teriyaki.\n\n1. Simmer soy sauce, mirin, and brown sugar until slightly syrupy.\n2. Sear salmon skin-side down until crisp, then flip and finish.\n3. Spoon the glaze over the salmon and let it bubble and coat.\n4. Serve over rice with scallion, sesame seeds, and cucumber.', 25, E'Flake plain seared salmon before glazing; serve with rice.', 4, '{"pescatarian","contains_fish","contains_soy","contains_gluten","dairy_free","contains_sesame"}'),
  ('Vegetable Yakisoba', 'japanese', E'Griddled noodles with cabbage and pepper in a tangy-sweet sauce.\n\n1. Boil udon briefly, drain, and pat dry so they griddle rather than steam.\n2. Stir-fry cabbage, carrot, and bell pepper over high heat until charred at the edges.\n3. Whisk soy sauce, hoisin, rice vinegar, and brown sugar into a sauce.\n4. Add noodles and sauce, toss hard until glossy; top with scallion and nori.', 25, E'Plain boiled noodles with a little sesame oil, set aside before the sauce.', 4, '{"vegan","vegetarian","dairy_free","contains_gluten","contains_soy"}'),
  ('Oyakodon (Chicken & Egg Rice Bowl)', 'japanese', E'Chicken and onion simmered in dashi and soy, set with barely-cooked egg over rice.\n\n1. Simmer sliced onion in dashi, soy sauce, mirin, and a little sugar until soft.\n2. Add sliced chicken thigh and cook through, 6 minutes.\n3. Pour beaten egg over the top in a spiral; cover and cook 90 seconds until just set.\n4. Slide over hot rice and finish with scallion.', 25, E'Spoon out plain chicken and fully-set egg with rice; skip the broth.', 4, '{"contains_poultry","contains_egg","contains_fish","contains_soy","contains_gluten","dairy_free"}'),
  ('Cold Soba with Sesame Dressing', 'japanese', E'Chilled buckwheat noodles in a nutty sesame dressing with cucumber and scallion.\n\n1. Boil soba, then rinse under cold water until completely cool; drain well.\n2. Whisk tahini, soy sauce, rice vinegar, sesame oil, and a little sugar.\n3. Julienne cucumber and carrot.\n4. Toss noodles with dressing and vegetables; top with sesame seeds and nori.', 20, E'Plain cold noodles with a drop of sesame oil; snip short.', 4, '{"vegan","vegetarian","dairy_free","contains_gluten","contains_soy","contains_sesame"}'),
  ('Japanese Curry with Beef & Potatoes', 'japanese', E'A thick, gently sweet curry stewed with beef, potato, and carrot.\n\n1. Brown cubed beef in vegetable oil; set aside.\n2. Saute onion until golden, then add carrot and potato.\n3. Add beef broth and the beef; simmer 40 minutes until everything is tender.\n4. Stir in curry powder and a cornstarch slurry; simmer until thick and glossy. Serve over rice.', 60, E'Plain potato, carrot, and shredded beef with rice before the curry goes in.', 6, '{"contains_beef","dairy_free","gluten_free"}'),
  ('Kimchi Fried Rice', 'korean', E'Day-old rice fried hard with kimchi and gochujang, topped with a runny egg.\n\n1. Fry chopped kimchi in sesame oil until the edges caramelize.\n2. Stir in gochujang and a splash of the kimchi juice.\n3. Add cold cooked rice and press it into the pan to crisp before tossing.\n4. Top each bowl with a fried egg, scallion, and sesame seeds.', 20, E'Plain fried rice pulled before the kimchi and gochujang, with a fully-cooked egg.', 4, '{"contains_egg","contains_shellfish","contains_soy","contains_gluten","dairy_free","contains_sesame"}'),
  ('Korean Braised Tofu (Dubu Jorim)', 'korean', E'Pan-fried tofu slabs braised in a savory-spicy soy glaze.\n\n1. Slice tofu into thick slabs, pat very dry, and pan-fry until golden on both sides.\n2. Whisk soy sauce, korean chili flakes, garlic, brown sugar, sesame oil, and water.\n3. Pour over the tofu and simmer 10 minutes, spooning the sauce over, until reduced and sticky.\n4. Finish with scallion and sesame seeds; serve with rice.', 30, E'Set aside a plain fried tofu slab before braising; serve with rice.', 4, '{"vegan","vegetarian","dairy_free","contains_soy","contains_gluten","contains_sesame"}'),
  ('Bulgogi Lettuce Wraps', 'korean', E'Sweet-savory marinated beef seared hard and wrapped in cold lettuce.\n\n1. Marinate thinly sliced flank steak in soy sauce, brown sugar, garlic, ginger, and sesame oil for 20 minutes.\n2. Sear in a screaming hot pan in batches so it browns rather than steams.\n3. Set out romaine leaves, rice, and kimchi.\n4. Let everyone build their own wraps; top with scallion and sesame seeds.', 35, E'Plain seared beef chopped small with rice, no marinade-heavy pieces.', 5, '{"contains_beef","contains_soy","contains_gluten","dairy_free","contains_sesame"}'),
  ('Korean Soft Tofu Stew (Sundubu Jjigae)', 'korean', E'A bubbling red stew of soft tofu, zucchini, and mushrooms.\n\n1. Saute korean chili flakes and garlic in sesame oil until the oil turns red.\n2. Add vegetable broth, zucchini, mushrooms, and onion; simmer 8 minutes.\n3. Spoon in large curds of soft tofu and simmer 5 minutes more without stirring much.\n4. Crack an egg into the center, kill the heat, and serve immediately with rice.', 30, E'Ladle plain tofu and soft zucchini with rice before the chili goes in.', 4, '{"vegetarian","contains_soy","contains_egg","dairy_free","contains_sesame","gluten_free"}'),
  ('Korean Braised Pork Belly with Rice', 'korean', E'Pork belly braised until meltingly soft in a soy, ginger, and star anise broth.\n\n1. Blanch pork belly pieces 5 minutes, then drain.\n2. Braise in soy sauce, brown sugar, garlic, ginger, star anise, and water for 60 minutes.\n3. Uncover and reduce until the sauce coats the meat.\n4. Serve sliced over rice with kimchi and scallion.', 80, E'Plain braised pork rinsed of sauce and chopped very small, with rice.', 6, '{"contains_pork","contains_soy","contains_gluten","dairy_free"}'),
  ('Japchae (Glass Noodle Stir-Fry)', 'korean', E'Chewy noodles tossed with sesame, spinach, carrot, and mushrooms.\n\n1. Boil vermicelli noodles until just tender, then rinse and drain.\n2. Stir-fry carrot, onion, mushroom, and bell pepper separately so each keeps its texture.\n3. Wilt spinach briefly and squeeze dry.\n4. Toss everything with soy sauce, sesame oil, brown sugar, and sesame seeds.', 35, E'Plain noodles with a little sesame oil and soft carrot, snipped short.', 4, '{"vegan","vegetarian","dairy_free","contains_soy","contains_gluten","contains_sesame"}'),
  ('Vietnamese Chicken Pho', 'vietnamese', E'A clear, aromatic broth over rice noodles with poached chicken and a pile of herbs.\n\n1. Char onion and ginger directly over a burner until blackened in spots.\n2. Simmer with chicken broth, star anise, and fish sauce for 30 minutes; strain.\n3. Poach chicken breast in the broth, then shred.\n4. Serve over vermicelli with bean sprouts, thai basil, lime, and scallion.', 50, E'Plain broth and noodles with shredded chicken; skip the herbs and lime.', 5, '{"contains_poultry","contains_fish","dairy_free","gluten_free"}'),
  ('Banh Mi Bowls with Lemongrass Pork', 'vietnamese', E'All the banh mi flavors over rice — lemongrass pork, pickled carrot, cucumber, herbs.\n\n1. Marinate sliced pork shoulder in lemongrass, garlic, fish sauce, and brown sugar.\n2. Quick-pickle shredded carrot and daikon in rice vinegar and sugar for 20 minutes.\n3. Sear the pork hard until caramelized at the edges.\n4. Build bowls with rice, pork, pickles, cucumber, cilantro, and a little mayo.', 40, E'Plain seared pork chopped small with rice; skip the pickles and sauce.', 5, '{"contains_pork","contains_fish","contains_egg","dairy_free","gluten_free"}'),
  ('Vietnamese Caramel Salmon', 'vietnamese', E'Salmon simmered in a dark, savory caramel sauce that is sweet, salty, and deeply savory.\n\n1. Melt brown sugar with a splash of water until it darkens to a deep amber.\n2. Carefully add fish sauce, garlic, ginger, and black pepper.\n3. Nestle in salmon fillets and simmer, spooning sauce over, 10 minutes.\n4. Finish with scallion and serve over rice with cucumber.', 30, E'Flake plain salmon before the caramel; serve with rice.', 4, '{"pescatarian","contains_fish","dairy_free","gluten_free"}'),
  ('Lemongrass Tofu Vermicelli Bowls', 'vietnamese', E'Cold noodles under crisp lemongrass tofu, herbs, and a sweet-tart dressing.\n\n1. Press and cube tofu, toss with lemongrass, garlic, and soy sauce, then pan-fry until crisp.\n2. Cook vermicelli, rinse cold, and drain thoroughly.\n3. Whisk lime, soy sauce, brown sugar, garlic, and water into a dressing.\n4. Build bowls with noodles, tofu, cucumber, carrot, mint, and cilantro; pour dressing over.', 35, E'Plain crisp tofu cubes and cold noodles, no dressing.', 4, '{"vegan","vegetarian","dairy_free","contains_soy","contains_gluten"}'),
  ('Vietnamese Beef & Watercress Stir-Fry (Bo Luc Lac)', 'vietnamese', E'Cubed beef seared hard and tossed in a garlicky sauce, served over greens.\n\n1. Marinate cubed flank steak in soy sauce, fish sauce, garlic, and brown sugar.\n2. Sear in a very hot pan in a single layer, undisturbed, so it crusts.\n3. Toss briefly with more garlic and a splash of rice vinegar.\n4. Pile over romaine and red onion; serve with rice and lime.', 30, E'Plain seared beef cubes chopped small with rice.', 4, '{"contains_beef","contains_fish","contains_soy","contains_gluten","dairy_free"}'),
  ('Vietnamese Turmeric Fish with Dill (Cha Ca)', 'vietnamese', E'Turmeric-marinated fish seared with an almost absurd amount of fresh dill.\n\n1. Toss fish chunks with turmeric, garlic, ginger, and fish sauce; rest 20 minutes.\n2. Sear in vegetable oil until golden and just cooked.\n3. Add a huge handful of dill and scallion and toss only until they wilt.\n4. Serve over vermicelli with peanuts and lime.', 30, E'Plain seared fish flaked, with noodles; skip peanuts for under-4s.', 4, '{"pescatarian","contains_fish","contains_nuts","dairy_free","gluten_free"}')
) as v(title, cuisine_tag, body_md, time_minutes, notes, base_servings, dietary_tags)
where not exists (select 1 from recipes r where r.title = v.title);

