insert into recipes (title, cuisine_tag, body_md, time_minutes, toddler_variant_notes, source, base_servings, dietary_tags)
select v.title, v.cuisine_tag, v.body_md, v.time_minutes, v.notes, 'curated', v.base_servings, v.dietary_tags::text[]
from (values
  ('Mapo Tofu', 'chinese', E'Silky tofu in a numbing, savory chili-bean sauce over rice.\n\n1. Toast sichuan peppercorns and grind coarsely.\n2. Brown ground pork hard, then add garlic, ginger, and gochujang until fragrant.\n3. Add broth and simmer, then slide in cubed tofu and warm through without breaking it.\n4. Thicken with a cornstarch slurry, finish with the peppercorns and scallion. Serve over rice.', 30, E'Plain tofu cubes and rice, spooned out before the chili paste.', 4, '{"contains_pork","contains_soy","contains_gluten","dairy_free"}'),
  ('Kung Pao Chicken', 'chinese', E'Diced chicken with peanuts and dried chilies in a tangy-sweet sauce.\n\n1. Toss diced chicken with cornstarch and soy sauce; sear hard and set aside.\n2. Fry dried chilies and sichuan peppercorns in oil until fragrant.\n3. Add garlic, ginger, bell pepper, and celery; stir-fry 2 minutes.\n4. Return chicken, add soy, rice vinegar, and sugar; toss with peanuts and scallion. Serve over rice.', 30, E'Plain seared chicken and rice; peanuts are not suitable under 4.', 4, '{"contains_poultry","contains_nuts","contains_soy","contains_gluten","dairy_free"}'),
  ('Char Siu Style Pork with Rice', 'chinese', E'Sticky, lacquered roast pork with five spice and honey-sweet glaze.\n\n1. Marinate sliced pork shoulder in hoisin, soy sauce, brown sugar, five spice, and garlic for 30 minutes.\n2. Roast at 425F for 25 minutes, basting twice with the marinade.\n3. Broil 3 minutes to caramelize the edges.\n4. Rest, slice, and serve over rice with steamed bok choy.', 60, E'Plain roasted pork slices wiped of glaze, chopped small, with rice.', 5, '{"contains_pork","contains_soy","contains_gluten","dairy_free"}'),
  ('Egg Drop Soup with Corn', 'chinese', E'A silky, comforting broth with ribbons of egg and sweet corn.\n\n1. Bring chicken broth to a simmer with ginger and a splash of soy sauce.\n2. Add corn kernels and simmer 5 minutes.\n3. Thicken slightly with a cornstarch slurry.\n4. Turn off the heat and pour beaten egg in a thin stream while stirring in one direction; finish with scallion and sesame oil.', 20, E'This is already gentle — serve a small bowl, making sure the egg is fully set.', 4, '{"contains_egg","contains_soy","contains_gluten","dairy_free","contains_sesame"}'),
  ('Dry-Fried Green Beans with Garlic', 'chinese', E'Blistered green beans tossed with a huge amount of garlic and a savory glaze.\n\n1. Blister green beans in a hot dry-ish pan with a little oil until wrinkled and browned.\n2. Add a mountain of minced garlic and ginger; toss 30 seconds.\n3. Add soy sauce, rice vinegar, and a pinch of sugar; toss until it glazes.\n4. Finish with sesame oil and serve over rice.', 20, E'Set aside plain blistered beans before the garlic; chop into short pieces.', 4, '{"vegan","vegetarian","dairy_free","contains_soy","contains_gluten","contains_sesame"}'),
  ('Beef & Broccoli with Oyster Sauce', 'chinese', E'The takeout classic, done properly with a velveted beef and a glossy sauce.\n\n1. Toss sliced flank steak with cornstarch, soy sauce, and shaoxing wine; rest 15 minutes.\n2. Sear the beef hard in batches; set aside.\n3. Stir-fry broccoli with a splash of water until crisp-tender.\n4. Add oyster sauce, soy, and a cornstarch slurry; return beef and toss until glossy. Serve over rice.', 30, E'Plain seared beef and steamed broccoli before the sauce.', 4, '{"contains_beef","contains_shellfish","contains_soy","contains_gluten","dairy_free"}'),
  ('Sesame Ginger Tofu with Bok Choy', 'chinese', E'Crisp tofu and tender bok choy in a bright ginger-sesame sauce.\n\n1. Press and cube tofu, toss in cornstarch, and pan-fry until crisp on all sides.\n2. Stir-fry bok choy with garlic until the stems are just tender.\n3. Whisk soy sauce, rice vinegar, sesame oil, ginger, and brown sugar.\n4. Return the tofu, add the sauce, and toss until it clings. Top with sesame seeds; serve over rice.', 30, E'Plain crisp tofu and soft bok choy leaves before the sauce.', 4, '{"vegan","vegetarian","dairy_free","contains_soy","contains_gluten","contains_sesame"}'),
  ('Chinese Tomato & Egg Stir-Fry', 'chinese', E'A humble, deeply comforting home dish of softly scrambled egg and stewed tomato.\n\n1. Beat eggs with a pinch of salt and scramble softly in hot oil; remove while still glossy.\n2. Cook tomato wedges with a little sugar until they slump and release their juice.\n3. Return the eggs and fold gently so they stay in soft curds.\n4. Season with soy sauce and scallion; serve over rice.', 15, E'Perfect as is — just make sure the egg is fully cooked; serve with rice.', 4, '{"vegetarian","contains_egg","contains_soy","contains_gluten","dairy_free"}'),
  ('Classic Smash Burgers', 'american', E'Thin, craggy, hard-seared patties with melted cheddar on a toasted bun.\n\n1. Divide ground beef into loose balls; do not compact them.\n2. Smash flat on a screaming-hot griddle and season hard; do not move them.\n3. Flip after a deep crust forms, top with cheddar, and cook 1 minute more.\n4. Toast the buns in the fat and build with onion, pickle, and mustard.', 25, E'A plain patty with no seasoning crust, cut into strips, plus a piece of plain bun.', 4, '{"contains_beef","contains_dairy","contains_gluten","contains_sesame"}'),
  ('Baked Mac & Cheese', 'american', E'A proper baked mac with a real bechamel and a crunchy top.\n\n1. Cook macaroni one minute shy of al dente; drain.\n2. Make a roux with butter and flour, whisk in milk, and cook until it thickly coats a spoon.\n3. Melt in cheddar off the heat, season, and fold in the pasta.\n4. Top with buttered panko and bake at 375F for 20 minutes until browned and bubbling.', 45, E'Serve a small portion as is — it is already mild. Cool before serving.', 6, '{"vegetarian","contains_dairy","contains_gluten"}'),
  ('Sheet-Pan BBQ Chicken & Sweet Potatoes', 'american', E'Chicken thighs and sweet potato wedges lacquered in barbecue sauce.\n\n1. Toss sweet potato wedges with olive oil, smoked paprika, and salt; roast at 425F for 15 minutes.\n2. Add chicken thighs and roast 20 minutes more.\n3. Brush everything generously with barbecue sauce.\n4. Broil 4 minutes until the sauce caramelizes and sticks.', 50, E'Pull a piece of plain chicken and sweet potato before the sauce.', 5, '{"contains_poultry","dairy_free","gluten_free"}'),
  ('Turkey Chili with Beans', 'american', E'A weeknight chili that tastes like it simmered all day.\n\n1. Brown ground turkey with onion and bell pepper until well colored.\n2. Add garlic, chili powder, cumin, and smoked paprika; cook 1 minute.\n3. Stir in crushed tomatoes, black beans, kidney beans, and broth.\n4. Simmer 30 minutes until thick. Serve with cheddar and sour cream.', 45, E'Ladle out plain turkey and beans before the chili powder; mash the beans.', 6, '{"contains_poultry","contains_dairy","gluten_free"}'),
  ('Buttermilk-Style Roast Chicken with Potatoes', 'american', E'A yogurt-brined roast chicken over potatoes that crisp in the drippings.\n\n1. Coat chicken thighs in yogurt, garlic, lemon, and salt; rest at least 30 minutes.\n2. Toss quartered potatoes with olive oil and rosemary in a roasting pan.\n3. Wipe excess marinade off the chicken and set on top of the potatoes.\n4. Roast at 425F for 40 minutes until the skin is deeply browned.', 55, E'Plain chicken and soft potato, chopped small.', 5, '{"contains_poultry","contains_dairy","gluten_free"}'),
  ('New England Corn Chowder', 'american', E'A creamy, bacon-scented corn chowder thick with potato.\n\n1. Render chopped bacon until crisp; set aside, leaving the fat.\n2. Soften onion and celery in the fat, then add diced potato and chicken broth.\n3. Simmer until the potato is tender, then add corn and milk.\n4. Blend a ladleful and stir it back for body; top with the bacon and scallion.', 40, E'Blend a portion smooth before adding bacon; serve warm, not hot.', 5, '{"contains_pork","contains_dairy","gluten_free"}'),
  ('Black Bean Burgers', 'american', E'Hearty, well-seasoned bean burgers that actually hold together.\n\n1. Mash black beans coarsely, leaving some texture.\n2. Mix with sauteed onion, garlic, cumin, smoked paprika, and panko until it holds a patty.\n3. Chill 15 minutes, then sear 4 minutes per side until crusted.\n4. Serve on toasted buns with avocado, tomato, and red onion.', 35, E'Plain patty broken into pieces with a bit of avocado.', 4, '{"vegan","vegetarian","dairy_free","contains_gluten","contains_sesame"}'),
  ('Skillet Cornbread & White Bean Stew', 'american', E'A brothy white bean stew with kale, meant for tearing bread into.\n\n1. Saute onion, carrot, and celery in olive oil until soft and sweet.\n2. Add garlic, then white beans, crushed tomatoes, and broth; simmer 20 minutes.\n3. Stir in chopped kale and cook until tender.\n4. Finish with lemon and olive oil; serve with cornbread or crusty bread.', 40, E'Ladle plain beans and soft carrot, mashed lightly.', 5, '{"vegan","vegetarian","dairy_free","gluten_free"}'),
  ('Pork Chops with Apples & Mustard Pan Sauce', 'american', E'Seared chops with a sharp, glossy mustard sauce and soft apples.\n\n1. Sear seasoned pork chops until deeply browned; rest.\n2. Soften sliced onion and apple in the same pan.\n3. Deglaze with chicken broth and dijon, scraping up the fond.\n4. Swirl in butter and spoon the sauce over the chops.', 35, E'Plain seared pork chopped small and soft cooked apple.', 4, '{"contains_pork","contains_dairy","gluten_free"}'),
  ('Loaded Baked Potato Soup', 'american', E'Everything you put on a baked potato, turned into soup.\n\n1. Simmer diced potato in chicken broth with onion and garlic until completely tender.\n2. Mash roughly, leaving plenty of chunks.\n3. Stir in milk and cheddar off the heat until melted and smooth.\n4. Top with crisp bacon, scallion, and sour cream.', 40, E'Blend a small portion smooth and skip the bacon and scallion.', 5, '{"contains_pork","contains_dairy","gluten_free"}')
) as v(title, cuisine_tag, body_md, time_minutes, notes, base_servings, dietary_tags)
where not exists (select 1 from recipes r where r.title = v.title);

