  ('Char Siu Style Pork with Rice','pork shoulder',2,'lb',false),('Char Siu Style Pork with Rice','hoisin sauce',4,'tbsp',false),('Char Siu Style Pork with Rice','soy sauce',3,'tbsp',false),('Char Siu Style Pork with Rice','brown sugar',3,'tbsp',false),('Char Siu Style Pork with Rice','chinese five spice',1,'tsp',false),('Char Siu Style Pork with Rice','garlic',5,'clove',false),('Char Siu Style Pork with Rice','shaoxing wine',2,'tbsp',true),('Char Siu Style Pork with Rice','bok choy',4,'cup',false),('Char Siu Style Pork with Rice','white rice',2,'cup',false),
