insert into recipes (title, cuisine_tag, body_md, time_minutes, toddler_variant_notes, source, base_servings, dietary_tags)
select v.title, v.cuisine_tag, v.body_md, v.time_minutes, v.notes, 'curated', v.base_servings, v.dietary_tags::text[]
from (values
  ('Chicken Dijon with Mushrooms', 'french', E'Seared chicken in a creamy mustard pan sauce with mushrooms.\n\n1. Sear seasoned chicken thighs until golden; set aside.\n2. Brown mushrooms hard in the same pan, then add shallot and garlic.\n3. Deglaze with broth, whisk in dijon and cream, and simmer to thicken.\n4. Return the chicken and finish with thyme and parsley.', 35, E'Plain seared chicken chopped small; skip the mustard sauce.', 4, '{"contains_poultry","contains_dairy","gluten_free"}'),
  ('French Lentil Salad with Goat Cheese', 'french', E'Firm green lentils in a sharp dijon vinaigrette with herbs.\n\n1. Simmer puy lentils with a bay leaf until tender but still holding shape, 25 minutes.\n2. Whisk dijon, sherry vinegar, olive oil, and shallot into a vinaigrette.\n3. Toss the warm lentils in the dressing so they drink it up.\n4. Fold in parsley and carrot; top with crumbled feta.', 40, E'Plain lentils with a little olive oil, no vinaigrette.', 4, '{"vegetarian","contains_dairy","gluten_free"}'),
  ('Croque Monsieur Bake', 'french', E'A tray-baked take on the classic ham and gruyere sandwich under bechamel.\n\n1. Make a bechamel with butter, flour, and milk; season with dijon and nutmeg.\n2. Layer bread, ham, gruyere, and bechamel in a baking dish.\n3. Top with the remaining bechamel and more gruyere.\n4. Bake at 400F for 25 minutes until deeply browned and bubbling.', 45, E'A small square, cooled — it is mild already.', 5, '{"contains_pork","contains_dairy","contains_gluten"}'),
  ('Ratatouille with White Beans', 'french', E'Slow-cooked summer vegetables, made a full dinner with white beans.\n\n1. Cook eggplant in olive oil until collapsing; set aside.\n2. Repeat with zucchini, then bell pepper and onion, cooking each properly.\n3. Combine with garlic, crushed tomatoes, and thyme; simmer 20 minutes.\n4. Stir in white beans, season well, and finish with basil and olive oil.', 50, E'Perfect as is — mash a portion with a fork.', 4, '{"vegan","vegetarian","dairy_free","gluten_free"}'),
  ('Salmon en Papillote with Leeks', 'french', E'Salmon steamed in parchment with lemon, thyme, and soft leeks.\n\n1. Soften sliced leek in butter until sweet, 8 minutes.\n2. Lay salmon on parchment, top with the leeks, lemon slices, thyme, and a splash of broth.\n3. Fold the parchment into sealed packets.\n4. Bake at 400F for 15 minutes; open at the table.', 30, E'Flake plain steamed salmon and soft leek.', 4, '{"pescatarian","contains_fish","contains_dairy","gluten_free"}'),
  ('Chicken & Chorizo Paella', 'spanish', E'A one-pan rice dish with saffron, chorizo, and a crisp bottom crust.\n\n1. Brown chicken thighs and sliced chorizo in olive oil; set aside.\n2. Soften onion and bell pepper, then add garlic, smoked paprika, and saffron.\n3. Stir in paella rice to coat, add broth, and return the meat.\n4. Simmer without stirring 20 minutes, then rest 5 minutes so the bottom crisps.', 50, E'Plain rice and chicken from the top, before the crust and paprika-heavy edges.', 6, '{"contains_poultry","contains_pork","dairy_free","gluten_free"}'),
  ('Spanish Tortilla with Potato & Onion', 'spanish', E'The thick, custardy potato omelette, good hot or at room temperature.\n\n1. Poach thinly sliced potato and onion gently in plenty of olive oil until soft, not browned.\n2. Drain and fold into beaten eggs; rest 10 minutes.\n3. Cook in a skillet over low heat until mostly set.\n4. Invert onto a plate and slide back to finish the other side.', 45, E'A small wedge, cooled — mild and soft already.', 5, '{"vegetarian","contains_egg","dairy_free","gluten_free"}'),
  ('Garlic Shrimp (Gambas al Ajillo)', 'spanish', E'Shrimp in sizzling garlic oil with chili and sherry vinegar, for bread-dipping.\n\n1. Warm a generous amount of olive oil with sliced garlic over low heat until barely golden.\n2. Add dried chili and smoked paprika.\n3. Raise the heat, add shrimp, and cook 2 minutes per side until just pink.\n4. Finish with sherry vinegar and parsley; serve with crusty bread.', 20, E'Plain poached shrimp chopped small; skip the garlic oil.', 4, '{"pescatarian","contains_shellfish","dairy_free","gluten_free"}'),
  ('Spanish Chickpea & Spinach Stew', 'spanish', E'A smoky, thick chickpea stew traditionally eaten in Lent.\n\n1. Fry garlic and smoked paprika in olive oil until fragrant.\n2. Add crushed tomatoes and cook down 5 minutes.\n3. Stir in chickpeas and a little broth; simmer 15 minutes, mashing some to thicken.\n4. Fold in spinach until wilted and finish with sherry vinegar.', 30, E'Plain chickpeas mashed, before the paprika.', 4, '{"vegan","vegetarian","dairy_free","gluten_free"}'),
  ('Pork & Pepper Pisto Bowls', 'spanish', E'Spanish stewed peppers and tomato over rice with seared pork.\n\n1. Cook onion, bell pepper, and zucchini slowly in olive oil until completely soft.\n2. Add garlic, smoked paprika, and crushed tomatoes; simmer 15 minutes.\n3. Sear seasoned pork shoulder pieces hard until browned.\n4. Serve the pisto over rice with the pork and a fried egg.', 45, E'Plain seared pork and rice; the pisto is soft enough on its own.', 5, '{"contains_pork","contains_egg","dairy_free","gluten_free"}'),
  ('Jerk Chicken with Rice & Beans', 'caribbean', E'Fiery marinated chicken with coconut rice and kidney beans.\n\n1. Marinate chicken thighs in jerk seasoning, allspice, garlic, ginger, lime, and a little brown sugar.\n2. Roast at 425F for 35 minutes until charred at the edges.\n3. Cook rice with coconut milk, kidney beans, thyme, and scallion.\n4. Serve with lime wedges.', 55, E'Rinse a piece of chicken of marinade and chop; plain coconut rice.', 5, '{"contains_poultry","dairy_free","gluten_free"}'),
  ('Caribbean Black Bean & Plantain Bowls', 'caribbean', E'Sweet fried plantain over cumin black beans and coconut rice.\n\n1. Simmer black beans with onion, garlic, cumin, and a bay leaf until thick.\n2. Cook rice with coconut milk and a pinch of salt.\n3. Fry sliced ripe plantain in vegetable oil until caramelized on both sides.\n4. Build bowls with rice, beans, plantain, avocado, and lime.', 40, E'Plain rice, mashed beans, and soft plantain — all mild.', 4, '{"vegan","vegetarian","dairy_free","gluten_free"}'),
  ('Cuban-Style Braised Pork (Lechon Asado)', 'caribbean', E'Citrus-and-garlic marinated pork braised until it shreds.\n\n1. Blend garlic, lime, orange, cumin, and oregano into a mojo marinade.\n2. Marinate pork shoulder at least 30 minutes, ideally longer.\n3. Braise covered at 325F for 2.5 hours until fork-tender.\n4. Shred, crisp under the broiler, and serve with rice and black beans.', 180, E'Plain shredded pork rinsed of marinade with rice.', 8, '{"contains_pork","dairy_free","gluten_free"}'),
  ('Coconut Curry Fish with Plantain', 'caribbean', E'Fish poached in a mild coconut curry alongside fried plantain.\n\n1. Saute onion, bell pepper, garlic, and thyme in vegetable oil.\n2. Add curry powder and allspice; cook until fragrant.\n3. Pour in coconut milk and simmer 5 minutes, then poach the fish 8 minutes.\n4. Fry plantain slices separately and serve alongside with lime.', 35, E'Flake plain poached fish and serve with soft plantain.', 4, '{"pescatarian","contains_fish","dairy_free","gluten_free"}'),
  ('Caribbean Callaloo-Style Greens with Rice', 'caribbean', E'Collard greens stewed in coconut milk with thyme and allspice.\n\n1. Saute onion, garlic, and thyme in vegetable oil until soft.\n2. Add chopped collard greens and cook until they collapse.\n3. Pour in coconut milk and a little broth; simmer 20 minutes until silky.\n4. Season with allspice and serve over rice.', 40, E'Chop the greens very fine and serve with plain rice.', 4, '{"vegan","vegetarian","dairy_free","gluten_free"}'),
  ('West African Peanut Stew', 'african', E'A thick, savory peanut and tomato stew with sweet potato and greens.\n\n1. Saute onion, garlic, and ginger in vegetable oil.\n2. Stir in crushed tomatoes and unsweetened peanut butter until smooth.\n3. Add sweet potato and broth; simmer 25 minutes until tender.\n4. Fold in collard greens and cook until wilted; finish with lime.', 45, E'Peanut-based — not suitable under 4. Reserve plain sweet potato before the peanut butter goes in.', 5, '{"vegan","vegetarian","dairy_free","gluten_free","contains_nuts"}'),
  ('Moroccan Chicken Tagine with Apricots', 'african', E'Slow-braised chicken with warm spices, olives, and dried fruit.\n\n1. Brown chicken thighs in olive oil; set aside.\n2. Soften onion, then add ginger, cumin, coriander, cinnamon, and turmeric.\n3. Return the chicken with broth and dried apricots; simmer covered 40 minutes.\n4. Stir in olives, finish with lemon and cilantro, and serve over couscous.', 60, E'Plain braised chicken and couscous, before the olives.', 5, '{"contains_poultry","dairy_free","contains_gluten"}'),
  ('Egyptian Koshari', 'african', E'Rice, lentils, and pasta under spiced tomato sauce and fried onions.\n\n1. Cook brown lentils and rice separately until tender.\n2. Boil elbow macaroni until al dente.\n3. Simmer crushed tomatoes with garlic, cumin, and vinegar into a sharp sauce.\n4. Layer rice, lentils, and pasta; top with the sauce and a heap of crisp fried onion.', 50, E'Plain rice and lentils, no sauce or fried onion.', 5, '{"vegan","vegetarian","dairy_free","contains_gluten"}'),
  ('Berbere Roasted Cauliflower & Chickpeas', 'african', E'Cauliflower and chickpeas roasted hard with berbere, cooled with yogurt.\n\n1. Toss cauliflower and chickpeas with olive oil, berbere, and salt.\n2. Roast at 425F for 30 minutes until charred at the edges.\n3. Stir lemon and garlic into greek yogurt.\n4. Serve over rice with the yogurt and plenty of cilantro.', 40, E'Reserve plain roasted cauliflower and chickpeas before the berbere.', 4, '{"vegetarian","contains_dairy","gluten_free"}'),
  ('Hungarian Chicken Paprikash', 'eastern_european', E'Chicken braised in a deeply paprika-red sauce finished with sour cream.\n\n1. Brown chicken thighs in butter; set aside.\n2. Cook onion slowly until very soft, then stir in a large amount of sweet paprika off the heat.\n3. Add broth and the chicken; simmer 30 minutes.\n4. Temper sour cream with hot liquid, stir it in off the heat, and serve over egg noodles.', 50, E'Plain chicken and buttered noodles before the sauce.', 5, '{"contains_poultry","contains_dairy","contains_gluten","contains_egg"}'),
  ('Polish Sausage with Sauerkraut & Potatoes', 'eastern_european', E'A one-pan bake of sausage, sauerkraut, and potatoes with caraway.\n\n1. Toss quartered potatoes with oil, caraway, and salt; roast at 425F for 20 minutes.\n2. Add sliced sausage and drained sauerkraut to the pan.\n3. Roast 20 minutes more until the sausage browns and the kraut crisps at the edges.\n4. Finish with dijon and parsley.', 50, E'Plain roasted potato; the sausage and kraut are too salty for little ones.', 5, '{"contains_pork","dairy_free","gluten_free"}'),
  ('Mushroom & Dill Stroganoff', 'eastern_european', E'A vegetarian stroganoff built on deeply browned mushrooms.\n\n1. Brown mushrooms hard in butter, in batches, until they squeak and color.\n2. Add onion and garlic, then dust with flour and cook 1 minute.\n3. Whisk in broth and simmer to thicken.\n4. Stir in sour cream and dill off the heat; serve over egg noodles.', 35, E'Plain buttered noodles set aside before the sauce.', 4, '{"vegetarian","contains_dairy","contains_gluten","contains_egg"}'),
  ('Borscht with Beans', 'eastern_european', E'A ruby beet soup made a full dinner with white beans, finished with dill.\n\n1. Saute onion, carrot, and celery in olive oil until soft.\n2. Add grated beets, crushed tomatoes, and broth; simmer 30 minutes until the beets are tender.\n3. Stir in white beans and a splash of vinegar to set the color.\n4. Serve with a spoon of sour cream and a lot of dill.', 50, E'Blend a small portion smooth; skip the vinegar and sour cream.', 5, '{"vegetarian","contains_dairy","gluten_free"}')
) as v(title, cuisine_tag, body_md, time_minutes, notes, base_servings, dietary_tags)
where not exists (select 1 from recipes r where r.title = v.title);

