  ('Chicken Dijon with Mushrooms','chicken thighs',2,'lb',false),('Chicken Dijon with Mushrooms','mushroom',10,'oz',false),('Chicken Dijon with Mushrooms','dijon mustard',3,'tbsp',false),('Chicken Dijon with Mushrooms','heavy cream',0.75,'cup',false),('Chicken Dijon with Mushrooms','chicken broth',1,'cup',false),('Chicken Dijon with Mushrooms','garlic',3,'clove',false),('Chicken Dijon with Mushrooms','thyme',1,'tsp',false),('Chicken Dijon with Mushrooms','yellow onion',1,'each',false),('Chicken Dijon with Mushrooms','parsley',1,'bunch',true),
  ('French Lentil Salad with Goat Cheese','puy lentils',1.5,'cup',false),('French Lentil Salad with Goat Cheese','feta',4,'oz',false),('French Lentil Salad with Goat Cheese','dijon mustard',2,'tbsp',false),('French Lentil Salad with Goat Cheese','sherry vinegar',2,'tbsp',false),('French Lentil Salad with Goat Cheese','olive oil',5,'tbsp',false),('French Lentil Salad with Goat Cheese','carrot',2,'each',false),('French Lentil Salad with Goat Cheese','parsley',1,'bunch',false),('French Lentil Salad with Goat Cheese','bay leaf',1,'each',true),('French Lentil Salad with Goat Cheese','red onion',0.5,'each',false),
