on conflict (recipe_id, ingredient_id) do nothing;

-- ===========================================================================
-- Reconcile: derive contains_* from ingredient allergens, then fail safe.
-- Same logic as 20260728000600, re-run so it covers everything added above.
-- ===========================================================================

update recipes r
   set dietary_tags = (
     select coalesce(array_agg(distinct t), '{}')
     from unnest(r.dietary_tags || array(
       select 'contains_' || case a when 'tree_nuts' then 'nuts' else a end
       from recipe_ingredients ri
       join ingredients i on i.id = ri.ingredient_id
       cross join unnest(i.allergens) a
       where ri.recipe_id = r.id
     )) t
   )
 where exists (
   select 1 from recipe_ingredients ri
   join ingredients i on i.id = ri.ingredient_id
   where ri.recipe_id = r.id and array_length(i.allergens, 1) > 0
 );

update recipes r set dietary_tags = array_remove(r.dietary_tags, 'vegan')
 where 'vegan' = any(r.dietary_tags)
   and exists (select 1 from recipe_ingredients ri join ingredients i on i.id = ri.ingredient_id
               where ri.recipe_id = r.id and i.allergens && array['egg','dairy','fish','shellfish']);

update recipes r set dietary_tags = array_remove(r.dietary_tags, 'vegetarian')
 where 'vegetarian' = any(r.dietary_tags)
   and exists (select 1 from recipe_ingredients ri join ingredients i on i.id = ri.ingredient_id
               where ri.recipe_id = r.id and i.allergens && array['fish','shellfish']);

-- NEW GUARD. contains_pork / contains_beef / contains_poultry have no backing
-- allergen token, so nothing above can infer or contradict them. A meat dish
-- mis-tagged vegetarian would therefore be served to a vegetarian household
-- with nothing to catch it. Strip the claim wherever a meat tag is present.
update recipes r
   set dietary_tags = array_remove(array_remove(r.dietary_tags, 'vegan'), 'vegetarian')
 where r.dietary_tags && array['contains_pork','contains_beef','contains_poultry']
   and r.dietary_tags && array['vegan','vegetarian'];

-- Likewise pescatarian, which forbids the same three.
update recipes r
   set dietary_tags = array_remove(r.dietary_tags, 'pescatarian')
 where 'pescatarian' = any(r.dietary_tags)
   and r.dietary_tags && array['contains_pork','contains_beef','contains_poultry'];
